import { useEffect } from 'react'
import { useQuery } from '@tanstack/react-query'
import { useWorkspaceStore } from '@/app/store/workspaceStore'
import { workplacesService } from '@/integrations/supabase/workplaces'
import { useTenant } from '@/app/providers/TenantProvider'

/**
 * Loads workplaces for the active tenant and auto-selects the first one
 * when no workplace is currently selected.
 */
export function useDefaultWorkplace() {
  const workplaceId = useWorkspaceStore((s) => s.workplaceId)
  const setWorkplaceId = useWorkspaceStore((s) => s.setWorkplaceId)
  const { manifest } = useTenant()
  const tenantId = manifest?.tenantId ?? ''

  const query = useQuery({
    queryKey: ['workplaces', tenantId],
    queryFn: () => workplacesService.listWorkplaces(tenantId),
    enabled: !!tenantId,
  })

  useEffect(() => {
    if (workplaceId) return
    const list = query.data
    if (list && list.length > 0) {
      setWorkplaceId(list[0].id)
    }
  }, [query.data, workplaceId, setWorkplaceId])

  return query
}
